 doc=SimpleDocTemplate(str(OUT/(slug+'.pdf')),pagesize=A4,rightMargin=42,leftMargin=42,topMargin=38,bottomMargin=62,title=title+' · pracTICAtecnica.com',author='GICM Desarrollo de Sistemas Digitales y Constructivos ICM');doc.build(story,onFirstPage=footer,onLaterPages=footer)
